// slides/compile.js
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = 'State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts';
pres.author = 'Generated from JetBrains State of Developer Ecosystem Report 2024';

const theme = {
  primary: "264653",    // dark teal - titles
  secondary: "2a9d8f",  // teal - accents
  accent: "e9c46a",     // gold - highlights
  light: "f4a261",      // orange - warm accent
  bg: "f2e9e4"          // light background
};

// Load and create all slides in order
for (let i = 1; i <= 6; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => console.log('Created: ./output/final_deck.pptx'))
  .catch(err => console.error('Error:', err));

